class VisitedPages {
    private final LinkedHashSet<String> pages = new LinkedHashSet<>();

    void visit(String url) {
        pages.remove(url); // jesli istnieje, usun (potem dodamy na koniec)
        pages.add(url);
        if (pages.size() > 5) {
            Iterator<String> it = pages.iterator();
            it.next();
            it.remove(); // usun najstarszy
        }
    }

    public String toString() { return pages.toString(); }
}

