static void visit(String task, Map<String, List<String>> deps, LinkedHashSet<String> order) {
    if (order.contains(task)) return;
    for (String dep : deps.getOrDefault(task, List.of())) {
        visit(dep, deps, order);
    }
    order.add(task);
}

