Map<Integer, List<Integer>> graph = Map.of(
    1, List.of(2, 3), 2, List.of(1, 4), 3, List.of(1, 5),
    4, List.of(2), 5, List.of(3)
);
int start = 1;

LinkedHashSet<Integer> visitOrder = new LinkedHashSet<>();
Queue<Integer> queue = new LinkedList<>();
queue.add(start);
visitOrder.add(start);

while (!queue.isEmpty()) {
    int node = queue.poll();
    for (int neighbor : graph.getOrDefault(node, List.of())) {
        if (visitOrder.add(neighbor)) { // add() zwraca true, jesli faktycznie dodal (nowy)
            queue.add(neighbor);
        }
    }
}
