static void permute(List<Integer> arr, int k, LinkedHashSet<List<Integer>> result) {
    if (k == arr.size()) {
        result.add(new ArrayList<>(arr));
        return;
    }
    for (int i = k; i < arr.size(); i++) {
        Collections.swap(arr, k, i);
        permute(arr, k + 1, result);
        Collections.swap(arr, k, i);
    }
}

