Map<String, List<String>> graph = Map.of(
    "A", List.of("B"), "B", List.of("C"), "C", List.of("A", "D"), "D", List.of()
);

Set<String> visited = new HashSet<>();
LinkedHashSet<String> path = new LinkedHashSet<>();

boolean hasCycle = dfs("A", graph, visited, path);
System.out.println("Cykl znaleziony: " + hasCycle);
if (hasCycle) System.out.println("Sciezka: " + path);

static boolean dfs(String node, Map<String, List<String>> graph, Set<String> visited, LinkedHashSet<String> path) {
    if (path.contains(node)) return true; // cykl!
    if (visited.contains(node)) return false;

    visited.add(node);
    path.add(node);
    for (String neighbor : graph.getOrDefault(node, List.of())) {
        if (dfs(neighbor, graph, visited, path)) return true;
    }
    path.remove(node); // backtracking
    return false;
}

record Transakcja(String kategoria, double kwota) {}

List<Transakcja> transakcje = List.of(
    new Transakcja("Jedzenie", 50), new Transakcja("Transport", 30),
    new Transakcja("Jedzenie", 80), new Transakcja("Rozrywka", 120),
    new Transakcja("Transport", 45)
);

